/**
 * QuickPulse metric counter names.
 * @internal
 */
export enum QuickPulseCounter {
  // Memory
  COMMITTED_BYTES = "\\Memory\\Committed Bytes",

  // CPU
  PROCESSOR_TIME = "\\Processor(_Total)\\% Processor Time",

  // Request
  REQUEST_RATE = "\\ApplicationInsights\\Requests/Sec",
  REQUEST_FAILURE_RATE = "\\ApplicationInsights\\Requests Failed/Sec",
  REQUEST_DURATION = "\\ApplicationInsights\\Request Duration",

  // Dependency
  DEPENDENCY_RATE = "\\ApplicationInsights\\Dependency Calls/Sec",
  DEPENDENCY_FAILURE_RATE = "\\ApplicationInsights\\Dependency Calls Failed/Sec",
  DEPENDENCY_DURATION = "\\ApplicationInsights\\Dependency Call Duration",

  // Exception
  EXCEPTION_RATE = "\\ApplicationInsights\\Exceptions/Sec",
}

/**
 * Performance metric counter names.
 * @internal
 */
export enum PerformanceCounter {
  // Memory
  PRIVATE_BYTES = "\\Process(??APP_WIN32_PROC??)\\Private Bytes",
  AVAILABLE_BYTES = "\\Memory\\Available Bytes",

  // CPU
  PROCESSOR_TIME = "\\Processor(_Total)\\% Processor Time",
  PROCESS_TIME_STANDARD = "\\Process(??APP_WIN32_PROC??)\\% Processor Time",
  PROCESS_TIME_NORMALIZED = "\\Process(??APP_WIN32_PROC??)\\% Processor Time Normalized",

  // Requests
  REQUEST_RATE = "\\ASP.NET Applications(??APP_W3SVC_PROC??)\\Requests/Sec",
  REQUEST_DURATION = "\\ASP.NET Applications(??APP_W3SVC_PROC??)\\Request Execution Time",

  // Exception
  EXCEPTION_RATE = "\\.NET CLR Exceptions(??APP_CLR_PROC??)\\# of Exceps Thrown / sec",
  // I/O
  IO_RATE = "\\Process(??APP_WIN32_PROC??)\\IO Data Bytes/sec",
}

/**
 * Map a PerformanceCounter/QuickPulseCounter to a QuickPulseCounter. If no mapping exists, mapping is *undefined*
 * @internal
 */
export const PerformanceToQuickPulseCounter: { [key: string]: QuickPulseCounter } = {
  [PerformanceCounter.PROCESSOR_TIME]: QuickPulseCounter.PROCESSOR_TIME,
  [PerformanceCounter.REQUEST_RATE]: QuickPulseCounter.REQUEST_RATE,
  [PerformanceCounter.REQUEST_DURATION]: QuickPulseCounter.REQUEST_DURATION,

  // Remap quick pulse only counters
  [QuickPulseCounter.COMMITTED_BYTES]: QuickPulseCounter.COMMITTED_BYTES,
  [QuickPulseCounter.REQUEST_FAILURE_RATE]: QuickPulseCounter.REQUEST_FAILURE_RATE,
  [QuickPulseCounter.DEPENDENCY_RATE]: QuickPulseCounter.DEPENDENCY_RATE,
  [QuickPulseCounter.DEPENDENCY_FAILURE_RATE]: QuickPulseCounter.DEPENDENCY_FAILURE_RATE,
  [QuickPulseCounter.DEPENDENCY_DURATION]: QuickPulseCounter.DEPENDENCY_DURATION,
  [QuickPulseCounter.EXCEPTION_RATE]: QuickPulseCounter.EXCEPTION_RATE,
};

/**
 * QuickPulse document types.
 * @internal
 */
export type QuickPulseDocumentType =
  "Event" | "Exception" | "Trace" | "Metric" | "Request" | "RemoteDependency" | "Availability";
/**
 * QuickPulse telemetry types.
 * @internal
 */
export type QuickPulseType =
  | "EventTelemetryDocument"
  | "ExceptionTelemetryDocument"
  | "TraceTelemetryDocument"
  | "MetricTelemetryDocument"
  | "RequestTelemetryDocument"
  | "DependencyTelemetryDocument"
  | "AvailabilityTelemetryDocument";

/**
 * OneSettings control-plane hostname.
 *
 * OneSettings is the Azure Monitor control plane that lets the ingestion team dynamically toggle
 * SDK features (e.g. SDK stats) and swap ingestion endpoints at runtime.
 * @internal
 */
export const ONE_SETTINGS_CNAME = "https://settings.sdk.monitor.azure.com";
/**
 * OneSettings configuration (e1) endpoint — returns the full settings payload.
 * @internal
 */
export const ONE_SETTINGS_CONFIG_URL = ONE_SETTINGS_CNAME + "/AzMonSDKDynamicConfiguration";
/**
 * OneSettings change-detection (e2) endpoint — cheap ETag poll used to detect changes.
 * @internal
 */
export const ONE_SETTINGS_CHANGE_URL = ONE_SETTINGS_CNAME + "/AzMonSDKDynamicConfigurationChanges";
/**
 * Default refresh interval between OneSettings polls, in milliseconds (1 hour).
 * Milliseconds are used because JS timers (`setTimeout`) are millisecond-based.
 * @internal
 */
export const ONE_SETTINGS_DEFAULT_REFRESH_INTERVAL_MS = 3600 * 1000;
/**
 * Maximum refresh interval between OneSettings polls, in milliseconds (24 hours).
 * @internal
 */
export const ONE_SETTINGS_MAX_REFRESH_INTERVAL_MS = 24 * 60 * 60 * 1000;
/**
 * Base interval, in milliseconds, for exponential backoff after transient OneSettings errors.
 * @internal
 */
export const ONE_SETTINGS_BACKOFF_BASE_MS = 3600 * 1000;
/**
 * OneSettings feature key that gates internal SDK stats.
 * @internal
 */
export const ONE_SETTINGS_FEATURE_SDK_STATS = "FEATURE_SDK_STATS";
/**
 * OneSettings feature key that independently gates customer-facing SDK stats.
 * @internal
 */
export const ONE_SETTINGS_FEATURE_CUSTOMER_SDK_STATS = "FEATURE_CUSTOMER_SDK_STATS";
/**
 * OneSettings feature key that gates offline telemetry storage and replay.
 * @internal
 */
export const ONE_SETTINGS_FEATURE_LOCAL_STORAGE = "FEATURE_LOCAL_STORAGE";
/**
 * Namespace targeting sent with OneSettings requests to select the Node.js configuration bucket.
 * @internal
 */
export const ONE_SETTINGS_NODEJS_TARGETING: Readonly<Record<string, string>> = {
  namespaces: "nodejs",
};
/**
 * HTTP status codes for which a failed OneSettings request should be retried with backoff.
 * @internal
 */
export const ONE_SETTINGS_RETRYABLE_STATUS_CODES: readonly number[] = [
  401, // Unauthorized
  403, // Forbidden
  408, // Request Timeout
  429, // Too Many Requests
  500, // Internal Server Error
  502, // Bad Gateway
  503, // Service Unavailable
  504, // Gateway Timeout
];
